package com.quincaisoft.integrations;
import com.quincaisoft.integrations.infrastructure.MtnCollectionAdapter;import com.quincaisoft.integrations.api.CollectionProvider;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.net.*;import java.util.*;
class MtnAdapterTest {
 MtnCollectionAdapter.Configuration config(){return new MtnCollectionAdapter.Configuration(URI.create("https://sandbox.momodeveloper.mtn.com"),"sandbox","test-user","test-credential","test-subscription",false);}
 CollectionProvider.Intent intent(){return new CollectionProvider.Intent(UUID.randomUUID(),"invoice-test","237600000000","100","EUR");}
 @Test void acceptedIsPendingAndIncludesHeaders(){var calls=new ArrayList<String>();var a=new MtnCollectionAdapter(config(),(m,u,h,b)->{calls.add(u.getPath());assertEquals("sandbox",h.get("X-Target-Environment"));if(u.getPath().endsWith("token"))return new MtnCollectionAdapter.Response(200,"{\"access_token\":\"synthetic\"}");assertNotNull(h.get("X-Reference-Id"));return new MtnCollectionAdapter.Response(202,"");});assertEquals(CollectionProvider.Outcome.PENDING,a.initiate(intent()).outcome());assertEquals(2,calls.size());}
 @Test void timeoutIsUnknown(){var a=new MtnCollectionAdapter(config(),(m,u,h,b)->{throw new java.io.IOException("synthetic timeout");});assertEquals(CollectionProvider.Outcome.UNKNOWN,a.initiate(intent()).outcome());}
 @Test void verifiedSandboxNeverLive(){var i=intent();var a=new MtnCollectionAdapter(config(),(m,u,h,b)->u.getPath().endsWith("token")?new MtnCollectionAdapter.Response(200,"{\"access_token\":\"synthetic\"}"):new MtnCollectionAdapter.Response(200,"{\"status\":\"SUCCESSFUL\",\"amount\":\"100\",\"currency\":\"EUR\",\"externalId\":\"invoice-test\",\"financialTransactionId\":\"test-id\",\"payer\":{\"partyIdType\":\"MSISDN\",\"partyId\":\"237600000000\"}}"));assertEquals(CollectionProvider.Outcome.SANDBOX_VERIFIED,a.query(i).outcome());}
 @Test void unsafeOriginsAndCurrencyRejected(){assertThrows(IllegalArgumentException.class,()->new MtnCollectionAdapter.Configuration(URI.create("https://example.com"),"sandbox","u","p","k",false));var a=new MtnCollectionAdapter(config(),(m,u,h,b)->{fail("Must not call provider");return null;});var i=intent();assertThrows(IllegalArgumentException.class,()->a.initiate(new CollectionProvider.Intent(i.reference(),i.externalId(),i.phone(),"100","XAF")));}
 @Test void credentialsNotPrinted(){assertFalse(config().toString().contains("test-credential"));}
 @Test void successfulStatusWithWrongAmountIsNotVerified(){var a=new MtnCollectionAdapter(config(),(m,u,h,b)->u.getPath().endsWith("token")?new MtnCollectionAdapter.Response(200,"{\"access_token\":\"synthetic\"}"):new MtnCollectionAdapter.Response(200,"{\"status\":\"SUCCESSFUL\",\"amount\":\"999\",\"currency\":\"EUR\",\"externalId\":\"invoice-test\",\"financialTransactionId\":\"test-id\",\"payer\":{\"partyIdType\":\"MSISDN\",\"partyId\":\"237600000000\"}}"));assertEquals(CollectionProvider.Outcome.UNKNOWN,a.query(intent()).outcome());}
 @Test void liveCallsRequireExplicitActivation(){var c=new MtnCollectionAdapter.Configuration(URI.create("https://momoapi.momo.africa"),"mtncameroon","u","p","k",false);var a=new MtnCollectionAdapter(c,(m,u,h,b)->{fail("Live call must not execute");return null;});var i=intent();assertThrows(IllegalStateException.class,()->a.initiate(new CollectionProvider.Intent(i.reference(),i.externalId(),i.phone(),"100","XAF")));}
}
